    started = Session(s["upload_id"], s["chunk_size"], s["expires_at"])
    if record is not None:
        record(started)
    for n, offset in enumerate(range(0, len(data), CHUNK)):
        part = data[offset : offset + CHUNK]
        _call(transport, "PUT", f"{BASE}/uploads/{started.upload_id}/parts/{n}", part, {"Content-MD5": hashlib.md5(part).hexdigest()})
    commit = {"checksum": hashlib.sha256(data).hexdigest()}
    return _stored(_call(transport, "POST", f"{BASE}/uploads/{started.upload_id}/commit", commit))
